    total = 0
    i = 0
    n = len(text)
    while i < n:
        j = i
        while j < n and text[j].isdigit():
            j += 1
        if j == i:
            break
        num = int(text[i:j])
        unit = text[j]
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num
        else:
            raise ValueError(f"Invalid unit: {unit}")
        i = j + 1
    return total
