    s = s.upper()

    # 创建一个字典，用于存储每个字符的长度
    char_lengths = {}
    for c in s:
        if c in char_lengths:
            char_lengths[c] += 1
        else:
            char_lengths[c] = 1

    # 遍历字符串，找到最长的回文子串
    longest_palindrome = ""
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            sub_str = s[i:j]
            if sub_str == sub_str[::-1] and len(sub_str) > len(longest_palindrome):
                longest_palindrome = sub_str

    return longest_palindrome
```
